def fit_window({{messages}}, {{tokenizer}}, {{budget}}):
    sys = [m for m in {{messages}} if m["role"] == "system"]
    rest = [m for m in {{messages}} if m["role"] != "system"]
    used = sum(len({{tokenizer}}.encode(m["content"])) for m in sys)
    out = []
    for m in reversed(rest):
        t = len({{tokenizer}}.encode(m["content"]))
        if used + t > {{budget}}: break
        out.append(m); used += t
    return sys + list(reversed(out))
